def _checkpoint_lock(path: str) -> threading.RLock:
    key = os.path.abspath(path)
    with _checkpoint_locks_guard:
        lock = _checkpoint_locks.get(key)
        if lock is None:
            lock = threading.RLock()
            _checkpoint_locks[key] = lock
        return lock


def _canonical_json_bytes(value: object) -> bytes:
    """Sorted-key, compact, unescaped-non-ASCII UTF-8 canonical JSON bytes."""
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def _checkpoint_state_hash(generation: int, anchor: dict, tip: dict, context: dict) -> str:
    """SHA-256 over the canonical JSON bytes of every field but state_hash."""
    body = {
        "generation": generation,
        "anchor": anchor,
        "tip": tip,
        "context": context,
    }
    return hashlib.sha256(_canonical_json_bytes(body)).hexdigest()


def _failed_advance(category: str) -> dict:
    return {"ok": False, "error": category}


def advance(
    path: str,
    docs: object,
    trust: object,
    anchor: object,
    now: object,
) -> dict:
    """Verify a range-export batch and durably checkpoint it at ``path``.

    ``docs`` is an ordered, non-empty batch of range deliveries verified with
    :func:`verify_range_exports` against ``trust`` and ``anchor`` at time
    ``now``: ``now`` must be a plain (non-boolean) non-negative integer; the
    first use of ``path`` requires a legal ``anchor`` (``{height, block_hash}``),
    while a later advance passes ``None`` (continue from the stored tip) or the
    stored tip's ``{height, block_hash}``.

    On success the checkpoint is written atomically (a uniquely named temp file
    in the same directory, fsynced and ``os.replace``d under a per-path lock)
    with key order ``generation, anchor, tip, context, state_hash``; generation
    starts at 1 and increments once per successful advance, so a failed
    verification never bumps it. The return value is the verifier result with
    the new ``generation`` appended as the final key.

    The same transaction appends the new checkpoint to the generation-history
    sidecar at ``path + ".history"`` (see the module docstring for the exact
    format): a missing sidecar is opened at ``base = {0, Z}`` for a first
    advance, or migrated from a pre-existing generation-``g`` checkpoint as
    ``base = {g-1, Z}`` with that checkpoint as the first record; an existing
    sidecar is strictly reloaded and replayed, and its last record must
    reproduce the stored checkpoint. Both files are written under the shared
    per-path lock; an ``io`` failure restores the original bytes of both
    best-effort (crash atomicity across the pair is not guaranteed).

    Every failure is ``{"ok": False, "error": category}`` with category one of
    ``input`` (bad arguments or checkpoint shape), ``auth``/``expired``/
    ``integrity`` (batch verification), ``state`` (an existing checkpoint or
    sidecar fails its key-order/type/hash/replay checks; it is never truncated
    or rebuilt) and ``io`` (the checkpoint cannot be read or written).
    """
    # Argument shape is validated before any file or verification work.
    if not isinstance(path, str) or not path:
        return _failed_advance(ERR_INPUT)
    if not _is_int(now) or now < 0:
        return _failed_advance(ERR_INPUT)

    lock = _checkpoint_lock(path)
    with lock:
        try:
            previous = _load_checkpoint(path)
            sidecar = _load_history(_history_path(path))
        except _CheckpointError as failure:
            return _failed_advance(failure.category)

        if previous is None:
            # A sidecar without its checkpoint is unrecoverable corruption.
            if sidecar is not None:
                return _failed_advance(ERR_STATE)
            # First use: the caller must pin a legal anchor.
            expected_anchor = _validate_advance_anchor(anchor)
            if expected_anchor is None:
                return _failed_advance(ERR_INPUT)
            generation = 0
            base = {"generation": 0, "hash": HISTORY_ZERO_HASH}
            records: list[dict] = []
        else:
            generation = previous["generation"]
            stored_tip = previous["tip"]
            if anchor is None:
                # Continue the continuous chain from the stored closed tip.
                expected_anchor = {
                    "height": stored_tip["height"],
                    "block_hash": stored_tip["tip_hash"],
                }
            else:
                expected_anchor = _validate_advance_anchor(anchor)
                if (
                    expected_anchor is None
                    or expected_anchor
                    != {
                        "height": stored_tip["height"],
                        "block_hash": stored_tip["tip_hash"],
                    }
                ):
                    return _failed_advance(ERR_INPUT)
            if sidecar is None:
                # Migrate a pre-existing checkpoint: it becomes the first
                # record over a zero base one generation below it.
                base = {

def _serialize_document(ordered: dict) -> bytes:
    """Compact UTF-8 JSON (non-ASCII unescaped) with one trailing newline."""
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _atomic_write_checkpoint(path: str, checkpoint: dict) -> None:
    """Write the checkpoint in declared key order and atomically replace ``path``."""
    ordered = {key: checkpoint[key] for key in CHECKPOINT_KEYS}
    _atomic_write_bytes(path, _serialize_document(ordered))


def _atomic_write_bytes(path: str, payload: bytes) -> None:
    """Atomically replace ``path`` with ``payload``.

    The temp file is fsynced before the replace and the directory afterwards,
    mirroring the main store's durability rules.
    """
    directory = os.path.dirname(os.path.abspath(path)) or "."
    os.makedirs(directory, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(prefix=".light-checkpoint-", dir=directory)
    promoted = False
    try:
        with os.fdopen(fd, "wb") as fh:
            fh.write(payload)
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(tmp_path, path)
        promoted = True
        _fsync_dir(directory)
    finally:
        if not promoted and os.path.exists(tmp_path):
            try:
                os.unlink(tmp_path)
            except OSError:
                pass


def _read_bytes_or_none(path: str) -> bytes | None:
    """Raw bytes of ``path`` (None when absent); other read errors propagate."""
    try:
        with open(path, "rb") as fh:
            return fh.read()
    except FileNotFoundError:
        return None


def _restore_bytes(path: str, original: bytes | None) -> None:
    """Best-effort compensation: put ``original`` back at ``path``.

    A file that did not exist is unlinked again. Any failure is swallowed —
    the caller already reports ``io`` and the next strict load surfaces the
    corruption as ``state``.
    """
    try:
        if original is None:
            os.unlink(path)
        else:
            _atomic_write_bytes(path, original)
    except OSError:
        pass


def _fsync_dir(directory: str) -> None:
    """Best-effort directory fsync so the checkpoint rename survives a crash."""
    try:
        dir_fd = os.open(directory, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    except OSError:
        return
    try:
        os.fsync(dir_fd)
    except OSError:
        pass
    finally:
        os.close(dir_fd)


# -- generation-history sidecar ------------------------------------------------

def _parse_finality_document(document: object) -> tuple[dict, dict, int, str]:
    """Stage 1 of the finality contract: exact key order and raw types.

    Every defect here is an input error. Returns the closed finalized
    boundary, the closed tip descriptor, the envelope's key version and its
    signature.
    """
    if not isinstance(document, dict) or tuple(document.keys()) != FINALITY_KEYS:
        raise _Failure(ERR_INPUT)
    finalized = _validate_header_anchor(document["finalized"])
    raw_tip = document["tip"]
    if not isinstance(raw_tip, dict) or tuple(raw_tip.keys()) != HEADER_TIP_KEYS:
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(raw_tip["tip_hash"]):
        raise _Failure(ERR_INPUT)
    if not _is_int(raw_tip["height"]) or raw_tip["height"] < 0:
        raise _Failure(ERR_INPUT)
    if not _is_int(raw_tip["length"]) or raw_tip["length"] < 1:
        raise _Failure(ERR_INPUT)
    if raw_tip["status"] not in (STATUS_PENDING, STATUS_CONFIRMED):
        raise _Failure(ERR_INPUT)
    tip = {key: raw_tip[key] for key in HEADER_TIP_KEYS}
    raw_auth = document["auth"]
    if not isinstance(raw_auth, dict) or tuple(raw_auth.keys()) != FINALITY_AUTH_KEYS:
        raise _Failure(ERR_INPUT)
    key_version = raw_auth["key_version"]
    signature = raw_auth["signature"]
    if not _is_int(key_version) or key_version < 1:
        raise _Failure(ERR_INPUT)
    if not isinstance(signature, str) or not crypto.is_hex128(signature):
        raise _Failure(ERR_INPUT)
    return finalized, tip, key_version, signature


def _authenticate_finality(
    document: dict, key_version: int, signature: str, signers: dict
) -> None:
    """Stage 2 of the finality contract: signer lookup and signature.

    Mirrors :func:`_authenticate_header_page`: the envelope's
    ``key_version`` selects the public key from ``trust.audit_signers``; an
    unknown version or an Ed25519 signature that does not verify over the
    domain-prefixed canonical bytes of the document without its ``auth`` is
    an auth failure.
    """
    public_key = signers.get(key_version)
    if public_key is None:
        raise _Failure(ERR_AUTH)
    unsigned = {key: document[key] for key in FINALITY_KEYS if key != "auth"}
    digest = hashlib.sha256(_finality_bytes(unsigned)).digest()
    if not crypto.verify_signature(public_key, digest, signature):
        raise _Failure(ERR_AUTH)


def apply_finality(path: object, document: object, trust: object) -> dict:
    """Apply a signed ``GET /v1/chain/finality`` credential to a checkpoint.

    The credential document has the exact top-level key order
    ``finalized, tip, auth``: ``finalized`` the irreversible boundary as
    ``{height, block_hash}``, ``tip`` the chain descriptor S and ``auth``

def _header_checkpoint_body(
    v: int,
    generation: int,
    anchor: dict,
    tip: dict,
    finalized: dict,
    steps: list,
) -> dict:
    """The hash-covered checkpoint body in its stored per-version form.

    Steps are normalized to the version-2+ shape internally; a version-1
    body projects them back to the legacy three-key shape so a legacy
    file's recorded digest still recomputes. The ``finalized`` boundary is
    a version-3 field only; version 2 carries the same steps but no
    boundary, so its recorded digest recomputes too.
    """
    step_keys = HEADER_STEP_KEYS if v == 1 else HEADER_STEP_V2_KEYS
    body = {
        "v": v,
        "generation": generation,
        "anchor": anchor,
        "tip": tip,
        "steps": [{key: step[key] for key in step_keys} for step in steps],
    }
    if v >= HEADER_CHECKPOINT_VERSION:
        body["finalized"] = finalized
    return body


def _header_checkpoint_hash(
    v: int,
    generation: int,
    anchor: dict,
    tip: dict,
    finalized: dict,
    steps: list,
) -> str:
    """SHA-256 over the canonical JSON bytes of every field but ``hash``."""
    return hashlib.sha256(
        _canonical_json_bytes(
            _header_checkpoint_body(
                v, generation, anchor, tip, finalized, steps
            )
        )
    ).hexdigest()


def _header_tip_advances(stored: dict, new: dict) -> bool:
    """Whether ``new`` is a legal successor tip of ``stored``.

    The tip may never drop in height; at the same height only the same
    ``block_hash`` moving from ``pending`` to ``confirmed`` is accepted.
    """
    if new["height"] != stored["height"]:
        return new["height"] > stored["height"]
    return (
        new["tip_hash"] == stored["tip_hash"]
        and stored["status"] == STATUS_PENDING
        and new["status"] == STATUS_CONFIRMED
    )


def _header_tip_reorgs(stored: dict, new: dict) -> bool:
    """Whether ``new`` is a legal reorg successor tip of ``stored``.

    The tip may never drop in height; at the same height a different
    ``block_hash`` — the reorganization itself — is accepted in either
    status, while the same hash may only move from ``pending`` to
    ``confirmed``. Anything else at the same height is a conflict.
    """
    if new["height"] != stored["height"]:
        return new["height"] > stored["height"]
    if new["tip_hash"] != stored["tip_hash"]:
        return True
    return (
        stored["status"] == STATUS_PENDING
        and new["status"] == STATUS_CONFIRMED
    )


def _validate_header_checkpoint_shape(data: object) -> dict:
    """Validate the exact key order and JSON types of one checkpoint document.

    Version-3 files carry the full key order
    ``v, generation, anchor, tip, finalized, steps, hash``; version-1 and
    version-2 files carry the legacy order without ``finalized`` and read
    with the boundary equal to the anchor.
    """
    if not isinstance(data, dict):
        raise _CheckpointError(ERR_STATE)
    if not _is_int(data.get("v")):
        raise _CheckpointError(ERR_STATE)
    if data["v"] == HEADER_CHECKPOINT_VERSION:
        # Version 3 requires the full key order including finalized.
        if tuple(data.keys()) != HEADER_CHECKPOINT_KEYS:
            raise _CheckpointError(ERR_STATE)
    elif data["v"] in (1, 2):
        if tuple(data.keys()) != (
            "v",
            "generation",
            "anchor",
            "tip",
            "steps",
            "hash",
        ):
            raise _CheckpointError(ERR_STATE)
    else:
        raise _CheckpointError(ERR_STATE)
    v = data["v"]
    generation = data["generation"]
    anchor = data["anchor"]
    tip = data["tip"]
    steps = data["steps"]
    digest = data["hash"]

    if not _is_int(v) or v not in HEADER_CHECKPOINT_VERSIONS:
        raise _CheckpointError(ERR_STATE)
    if not _is_int(generation) or generation < 1:
        raise _CheckpointError(ERR_STATE)
    if not isinstance(anchor, dict) or tuple(anchor.keys()) != HEADER_ANCHOR_KEYS:
        raise _CheckpointError(ERR_STATE)
    if not _is_int(anchor["height"]) or anchor["height"] < 0:
        raise _CheckpointError(ERR_STATE)
    if not crypto.is_hex64(anchor["block_hash"]):
        raise _CheckpointError(ERR_STATE)
    if not isinstance(tip, dict) or tuple(tip.keys()) != HEADER_TIP_KEYS:
        raise _CheckpointError(ERR_STATE)
    if not crypto.is_hex64(tip["tip_hash"]):
        raise _CheckpointError(ERR_STATE)
    if not _is_int(tip["height"]) or tip["height"] < 0:
        raise _CheckpointError(ERR_STATE)
    if not _is_int(tip["length"]) or tip["length"] < 1:
        raise _CheckpointError(ERR_STATE)
    if tip["status"] not in (STATUS_PENDING, STATUS_CONFIRMED):
        raise _CheckpointError(ERR_STATE)
    # Version 3 pins the finalized boundary explicitly; legacy versions
    # take the initial anchor as the boundary.
    if v == HEADER_CHECKPOINT_VERSION:
        finalized_raw = data["finalized"]
        if (
            not isinstance(finalized_raw, dict)
            or tuple(finalized_raw.keys()) != HEADER_ANCHOR_KEYS
        ):
            raise _CheckpointError(ERR_STATE)
        if not _is_int(finalized_raw["height"]) or finalized_raw["height"] < 0:
            raise _CheckpointError(ERR_STATE)
        if not crypto.is_hex64(finalized_raw["block_hash"]):
            raise _CheckpointError(ERR_STATE)
        finalized = {
            "height": finalized_raw["height"],
            "block_hash": finalized_raw["block_hash"],
        }
    else:
        finalized = {
            "height": anchor["height"],
            "block_hash": anchor["block_hash"],
        }
    if not isinstance(steps, list) or not steps:
        raise _CheckpointError(ERR_STATE)
    validated_steps = []
    for raw in steps:
        if not isinstance(raw, dict):
            raise _CheckpointError(ERR_STATE)
        if v == 1:
            # Legacy steps carry only the linear-batch fields; they replay
            # as linear steps with no locator request.
            if tuple(raw.keys()) != HEADER_STEP_KEYS:
                raise _CheckpointError(ERR_STATE)
            kind = "linear"
            locators = None
        else:
            if tuple(raw.keys()) != HEADER_STEP_V2_KEYS:
                raise _CheckpointError(ERR_STATE)
            kind = raw["kind"]
            if kind not in HEADER_STEP_KINDS:
                raise _CheckpointError(ERR_STATE)
            locators = raw["locators"]
            if kind == "linear":
                # A linear step never carries a locator request.
                if locators is not None:
                    raise _CheckpointError(ERR_STATE)
            elif not isinstance(locators, list) or not locators:
                raise _CheckpointError(ERR_STATE)
        if not crypto.is_hex64(raw["tip_hash"]):
            raise _CheckpointError(ERR_STATE)
        if not isinstance(raw["trust"], dict):
            raise _CheckpointError(ERR_STATE)
        if not isinstance(raw["documents"], list) or not raw["documents"]:
            raise _CheckpointError(ERR_STATE)
        validated_steps.append(
            {
                "kind": kind,
                "tip_hash": raw["tip_hash"],
                "trust": raw["trust"],
                "documents": raw["documents"],
                "locators": locators,
            }
        )
    if not crypto.is_hex64(digest):
        raise _CheckpointError(ERR_STATE)

    return {
        "v": v,
        "generation": generation,
        "anchor": {key: anchor[key] for key in HEADER_ANCHOR_KEYS},
        "tip": {key: tip[key] for key in HEADER_TIP_KEYS},
        "finalized": finalized,
        "steps": validated_steps,
        "hash": digest,
    }


def _replay_header_checkpoint(checkpoint: dict) -> tuple[list[dict], dict]:
    """Re-verify one shape-validated header checkpoint document.

    The recorded ``hash`` pins the document before any replay: a tampered
    version, generation, anchor, tip, finalized boundary or step is state
    corruption, not re-verified. Every stored step is then replayed against
    its own recorded pins — a ``linear`` step through
    :func:`verify_header_pages`, a ``locator`` step through
    :func:`verify_header_locator_pages` — the first from the checkpoint
    anchor, every later one from the previous step's closed tip (a locator
    step's matched anchor must equal that boundary), with the same
    tip-monotonicity rule as a live advance or reorg, and the final
    replayed tip must equal the stored one. The stored ``finalized``
    boundary must name the current replayed branch's anchor or a confirmed
    header on it (a reorg step prunes the fork it replaces from the
    tracked branch); a boundary belonging to a dropped fork or to a
    pending header is state corruption. Returns the verified per-step tip
    descriptors in step order.
    """
    recomputed = _header_checkpoint_hash(
        checkpoint["v"],
        checkpoint["generation"],
        checkpoint["anchor"],
        checkpoint["tip"],
        checkpoint["finalized"],
        checkpoint["steps"],
    )
    if recomputed != checkpoint["hash"]:
        raise _CheckpointError(ERR_STATE)

    steps = checkpoint["steps"]
    # Version 1 counts exactly one generation per recorded step. Version-2+
    # reorgs drop a suffix of steps while still incrementing the
    # generation, so the generation only bounds the step count from above.
    if checkpoint["v"] == 1:
        if checkpoint["generation"] != len(steps):
            raise _CheckpointError(ERR_STATE)
    elif checkpoint["generation"] < len(steps):
        raise _CheckpointError(ERR_STATE)

    expected_anchor = checkpoint["anchor"]
    tip: dict | None = None
    step_tips: list[dict] = []
    # The current branch as a height -> (block_hash, status) map, seeded
    # with the initial anchor (always a closed, confirmed chain point). A
    # reorg prunes the fork it replaces before the new headers are
    # recorded, so after the full replay the map describes exactly the
    # branch the checkpoint currently names.
    branch: dict[int, tuple[str, str]] = {
        checkpoint["anchor"]["height"]: (
            checkpoint["anchor"]["block_hash"],
            STATUS_CONFIRMED,
        )
    }
    for step in steps:
        if step["kind"] == "locator":
            result = verify_header_locator_pages(
                step["documents"],
                step["locators"],
                step["tip_hash"],
                step["trust"],
            )
        else:
            result = verify_header_pages(
                step["documents"], expected_anchor, step["tip_hash"], step["trust"]
            )
        if not result.get("ok"):
            raise _CheckpointError(ERR_STATE)
        if step["kind"] == "locator":
            # A reorg step must anchor exactly at its boundary: the closing
            # tip of the last retained step (or the initial anchor). The
            # fork it replaces is pruned from the tracked branch first.
            if result["anchor"] != expected_anchor:
                raise _CheckpointError(ERR_STATE)
            boundary_height = result["anchor"]["height"]
            for height in [h for h in branch if h > boundary_height]:
                del branch[height]
            legal = tip is None or _header_tip_reorgs(tip, result["tip"])
        else:
            legal = tip is None or _header_tip_advances(tip, result["tip"])
        if not legal:
            raise _CheckpointError(ERR_STATE)
        for document in step["documents"]:
            for header in document["headers"]:
                branch[header["height"]] = (header["block_hash"], header["status"])
        tip = result["tip"]
        # The closing tip is authoritative for its height: an empty
        # final page (the pending -> confirmed case) carries no headers
        # but still settles the tip's status.
        branch[tip["height"]] = (tip["tip_hash"], tip["status"])
        step_tips.append(tip)
        expected_anchor = {
            "height": tip["height"],
            "block_hash": tip["tip_hash"],
        }
    assert tip is not None  # steps is shape-guaranteed non-empty
    if tip != checkpoint["tip"]:
        raise _CheckpointError(ERR_STATE)

    # The finalized boundary must belong to the replayed current branch:
    # it names the anchor, or a confirmed header recorded on it. An
    # unknown height, a dropped-fork hash or a pending header is state
    # corruption.
    finalized = checkpoint["finalized"]
    entry = branch.get(finalized["height"])
    if entry is None or entry[0] != finalized["block_hash"]:
        raise _CheckpointError(ERR_STATE)
    if finalized != checkpoint["anchor"] and entry[1] != STATUS_CONFIRMED:
        raise _CheckpointError(ERR_STATE)
    return step_tips, branch


def _load_header_checkpoint_document(path: str) -> tuple[dict, list[dict], dict] | None:
    """Strictly load and re-verify a checkpoint, returning it, step tips, branch.

    Returns None when no file exists at ``path``. Otherwise validates the
    exact key order and JSON types, recomputes ``hash`` over the other
    fields, and replays every stored step. The third result maps each
    current-branch height to ``(block_hash, status)`` (forks pruned by
    reorgs are absent). Any defect is a ``state`` failure (unreadable JSON
    is ``state`` too, an unreadable file ``io``); the file is never
    truncated or rebuilt.
    """
    try:
        with open(path, "r", encoding="utf-8") as fh:
            text = fh.read()
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise _CheckpointError(ERR_IO) from exc

    try:
        data = json.loads(text)
    except (ValueError, UnicodeDecodeError) as exc:
        raise _CheckpointError(ERR_STATE) from exc
    checkpoint = _validate_header_checkpoint_shape(data)
    step_tips, branch = _replay_header_checkpoint(checkpoint)
    return checkpoint, step_tips, branch

def _validate_header_anchor(raw: object) -> dict:
    """Structural validation of a closed ``{height, block_hash}`` anchor."""
    if not isinstance(raw, dict) or tuple(raw.keys()) != HEADER_ANCHOR_KEYS:
        raise _Failure(ERR_INPUT)
    if not _is_int(raw["height"]) or raw["height"] < 0:
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(raw["block_hash"]):
        raise _Failure(ERR_INPUT)
    return {"height": raw["height"], "block_hash": raw["block_hash"]}


def _validate_header_trust(trust: object) -> dict:
    """Parse ``trust.audit_signers`` into ``{version: public_key}``.

    The list must be non-empty; every entry must carry a positive,
    non-boolean integer ``version`` and a 64-lowercase-hex ``public_key``.
    Versions must be unique. Any other defect is an input error.
    """
    if not isinstance(trust, dict):
        raise _Failure(ERR_INPUT)
    raw_signers = trust.get("audit_signers")
    if not isinstance(raw_signers, list) or not raw_signers:
        raise _Failure(ERR_INPUT)
    signers: dict[int, str] = {}
    for entry in raw_signers:
        if not isinstance(entry, dict):
            raise _Failure(ERR_INPUT)
        version = entry.get("version")
        public_key = entry.get("public_key")
        if not _is_int(version) or version < 1:
            raise _Failure(ERR_INPUT)
        if not crypto.is_hex64(public_key):
            raise _Failure(ERR_INPUT)
        if version in signers:
            raise _Failure(ERR_INPUT)
        signers[version] = public_key
    return signers


